		reachedLimit := limit > 0 && len(revs) >= limit
		if !reachedLimit {
			revs = append(revs, indexRevision{
				key:      ki.key,
				created:  created,
				modified: modified,
				version:  version,
			})
		} else if !withTotalCount {
			return false
		}
		total++
		return true
	})
	return revs, total
